rules=[dict(parent=p,gloss=g,words=ws.split('|'),physicalPage=pg,printedPage=pp,item=item,citation='CDIAL['+p.replace('-','.')+'];varghesekumar2015noira[Appendix A3, p. '+str(pp)+', item '+str(item)+']',evidence=ev) for p,g,ws,pg,pp,item,ev in spec]
acc=[];held=[];cells=[];cellindex={}
for f in (ROOT/'data/other/forms/raw_data/sil_noira_2015/manual_chunks').glob('items_*_hand_keyed.tsv'):
 for r in csv.DictReader(f.open(),delimiter='\t'):cellindex[(r['Item'],r['Site_Code'])]=r
