  ev=q['evidence']+' Visual inspection of PDF physical p. '+str(q['physicalPage'])+' confirms dental-stop glyphs misread as ɖ/ʈ by the stored source ledger. This link follows the printed reading, not an invented retroflex sound change. Stored form '+r['Form']+' and its durable ID are preserved pending a separately audited source correction. Final -e variants are retained in the same lexical family, without assigning an unsupported grammatical category.'
  acc.append(dict(record=r,parent=q['parent'],family=i,kind='reflex',citation=q['citation'],evidence=ev));cells.append(dict(recordId=r['ID'],storedForm=r['Form'],sourceCell=c,verifiedDentalStops=True,physicalPage=q['physicalPage'],verification='Visual reading of the original printed page; milk control checked again at 400 dpi. Only the stop-glyph mismatch is asserted.'))
